  INDEX `fk_address_country1_idx` (`country_id` ASC) VISIBLE,
  INDEX `fk_address_province1_idx` (`state_id` ASC) VISIBLE,
  INDEX `fk_address_municipality1_idx` (`municipality_id` ASC) VISIBLE,
  INDEX `fk_address_city1_idx` (`city_id` ASC) VISIBLE,
  INDEX `fk_address_sector1_idx` (`sector_id` ASC) VISIBLE,
  INDEX `fk_citizen_addresses_citizens1_idx` (`citizen_id` ASC) VISIBLE,
  CONSTRAINT `fk_address_country10`
    FOREIGN KEY (`country_id`)
    REFERENCES `countries` (`id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_address_province10`
    FOREIGN KEY (`state_id`)
    REFERENCES `states` (`id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_address_municipality10`
    FOREIGN KEY (`municipality_id`)
    REFERENCES `municipalities` (`id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_address_city10`
    FOREIGN KEY (`city_id`)
    REFERENCES `cities` (`id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_address_sector10`
    FOREIGN KEY (`sector_id`)
    REFERENCES `sectors` (`id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_citizen_addresses_citizens1`
    FOREIGN KEY (`citizen_id`)
    REFERENCES `citizens` (`id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE)
ENGINE = InnoDB;


-- -----------------------------------------------------
