CREATE TABLE IF NOT EXISTS `elections` (
  `id` INT NOT NULL,
  `election_id` VARCHAR(40) NOT NULL,
  `election_type` VARCHAR(120) NOT NULL,
  `election_date` DATE NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `active` TINYINT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `election_id_UNIQUE` (`election_id` ASC) VISIBLE)
ENGINE = InnoDB;


-- -----------------------------------------------------
-- Placeholder table for view `v_team_members`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `v_team_members` (`id` INT, `member_id` INT, `user_id` INT, `parent_id` INT, `member_since` INT, `citizen_id` INT, `citizen_uuid` INT, `id_card` INT, `first_name` INT, `last_name` INT, `member_count` INT, `level_count` INT);

-- -----------------------------------------------------
-- function get_team_level_count
-- -----------------------------------------------------

DELIMITER $$
CREATE FUNCTION get_team_level_count(_parent_id BIGINT)
RETURNS INT
BEGIN
	
	DECLARE _level_count INT DEFAULT 0;
    
    WITH RECURSIVE _team_levels (id, _level) AS
	(
		SELECT id, 1 _level
		FROM team_members
		WHERE parent_id = _parent_id
	  
		UNION ALL

		SELECT c.id, cp._level + 1
		FROM _team_levels AS cp 
		JOIN team_members AS c
			ON cp.id = c.parent_id
	)
    
    SELECT max(_level) FROM _team_levels
	INTO _level_count;
    
    IF _level_count IS NULL THEN
		SET _level_count = 0;
	END IF;
	
	RETURN _level_count;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure level_members
-- -----------------------------------------------------

DELIMITER $$
CREATE PROCEDURE level_members(IN _parent_id INT)
BEGIN
    
     WITH RECURSIVE _team_levels (id, _level) AS
	(
		SELECT id, 1 _level
		FROM team_members
		WHERE parent_id = _parent_id
	  
		UNION ALL

		SELECT c.id, cp._level + 1
		FROM _team_levels AS cp 
		JOIN team_members AS c
			ON cp.id = c.parent_id
	)

	SELECT _level, count(id) member_count FROM _team_levels
	GROUP BY _level
    ORDER BY _level ASC;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- View `v_team_members`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `v_team_members`;
CREATE  OR REPLACE VIEW `v_team_members` AS
SELECT t.id, t.member_id, t.user_id,  t.parent_id,  t.created_at AS member_since, t.citizen_id, c.citizen_id AS citizen_uuid, c.id_card, c.first_name, c.last_name,
	(
    SELECT COUNT(id)schedules
    FROM `team_members` AS t1
    WHERE t1.`parent_id` = t.id
  ) AS member_count,
  get_team_level_count(t.id) AS level_count
FROM team_members t
INNER JOIN citizens c
	ON c.id = t.citizen_id;

